    关系标签: SA(/[、，,]/u), 好感度: N(0, -200, 200, true), 好感阶段: DV(), 情意: NN(0, 100, true), 档差: DV(),
    联系方式: B(false),
    设定依据: E(['原文', '推定', '本卡规则'], '推定', ALIAS.设定依据),
