    try {
      const messages = readMessages();
      const fingerprint = hash(JSON.stringify(messages.map(m => [m.message_id, m.role, m.swipe_id ?? 0, m.swipes?.[m.swipe_id ?? 0] ?? m.message ?? '',m.dl4Inbox||null])));
