    if(!scanned){
      if(current)section.append(btn('开展实地勘测',()=>gateAction('勘测'+system.name,`我在${system.name}对本地行星和异常信号做实地勘测，登记观测到的目标和近场信号。`,'survey'),'btn primary','scan'));
